      subRoundRect(X(SHELL_W/2 + s*PIN_SPACING/2) - mm(PIN_SQ)/2, Y(ROLLER_Y) - mm(PIN_SQ)/2, mm(PIN_SQ), mm(PIN_SQ), mm(0.35));
